INSERT INTO clientes (id_cliente, nome, tipo_instituicao, cidade, nivel_complexidade, status, observacoes_gerais) VALUES (295, 'Lar São Francisco de Cuidados para Idosos', 'ILPI Privada', 'São Luís/MA', 'alta', 'ativo', 'A Conceição é extremamente comprometida com cuidado, mas evita conflitos administrativos. A equipe assistencial é emocionalmente sobrecarregada. Quando há incidente com residente, tudo vira prioridade máxima.');
