INSERT INTO clientes (id_cliente, nome, tipo_instituicao, cidade, nivel_complexidade, status, observacoes_gerais) VALUES (297, 'CAPS II Renascer', 'Saúde Mental Pública', 'São Luís/MA', 'alta', 'ativo', 'Ambiente muito sensível emocionalmente. A equipe trabalha sobrecarregada. Demandas urgentes surgem sem previsibilidade. Muitas decisões acontecem informalmente.');
INSERT INTO clientes (id_cliente, nome, tipo_instituicao, cidade, nivel_complexidade, status, observacoes_gerais) VALUES (298, 'CuidaBem Serviços Domiciliares', 'Home Care', 'São Luís/MA', 'alta', 'ativo', 'Cliente extremamente acelerado. Tudo acontece via WhatsApp. Marcela toma decisão emocional sob pressão. Mudanças de escala acontecem o tempo todo.');
INSERT INTO clientes (id_cliente, nome, tipo_instituicao, cidade, nivel_complexidade, status, observacoes_gerais) VALUES (299, 'REABILITA Centro de Reabilitação', 'Clínica de Reabilitação', 'São Luís/MA', 'alta', 'ativo', 'Equipe técnica muito boa, mas gestão financeira confusa. A Fernanda muda prioridades frequentemente conforme pressão dos convênios.');
