INSERT INTO clientes (id_cliente, nome, tipo_instituicao, cidade, nivel_complexidade, status, observacoes_gerais) VALUES (301, 'FarmaVida Farmácia Comunitária', 'Farmácia Popular', 'Caxias/MA', 'média', 'ativo', 'Operação muito baseada na memória do dono. Resistência inicial ao uso de sistema. Grande preocupação com perda financeira por erro operacional.');
