INSERT INTO projetos (id_projeto, id_contrato, titulo, descricao, data_inicio, data_fim_prevista, data_fim_real, valor_total, status, observacoes_gerais) VALUES (946, 295, 'Reorganização Operacional Assistencial', 'Foco em regularização urgente para auditoria da VISA prevista para o próximo mês. Ambiente de alta pressão por prazos regulatórios.', '2026-04-23', NULL, NULL, 3000.00, 'em andamento', NULL);
INSERT INTO projetos (id_projeto, id_contrato, titulo, descricao, data_inicio, data_fim_prevista, data_fim_real, valor_total, status, observacoes_gerais) VALUES (948, 297, 'Estruturação do Fluxo Operacional do CAPS', 'Caos imprevisível com excesso de informalidade. Correria no fechamento mensal e reuniões longas para alinhar fluxos.', '2026-04-28', '2026-05-28', NULL, 1500.00, 'em andamento', NULL);
INSERT INTO projetos (id_projeto, id_contrato, titulo, descricao, data_inicio, data_fim_prevista, data_fim_real, valor_total, status, observacoes_gerais) VALUES (950, 298, 'Estruturação da Operação de Escalas', 'Cliente extremamente acelerado. Acionamentos via WhatsApp e mudanças emocionais constantes. Necessidade de ritmo industrial nas escalas.', '2026-04-13', '2026-05-20', NULL, 2000.00, 'concluído', NULL);
INSERT INTO projetos (id_projeto, id_contrato, titulo, descricao, data_inicio, data_fim_prevista, data_fim_real, valor_total, status, observacoes_gerais) VALUES (952, 299, 'Organização do Fluxo de Atendimento e Faturamento', 'Gargalos administrativos e retrabalho financeiro. Pressão constante dos convênios por documentação de evolução clínica.', '2026-04-03', '2026-04-28', NULL, 2200.00, 'em andamento', NULL);
INSERT INTO projetos (id_projeto, id_contrato, titulo, descricao, data_inicio, data_fim_prevista, data_fim_real, valor_total, status, observacoes_gerais) VALUES (953, 296, 'Organização Administrativa do Convênio Municipal', 'Rotina afetiva mas com baixa organização formal. Medo constante de auditoria municipal por documentação incompleta.', '2026-02-12', NULL, NULL, 1000.00, 'concluído', NULL);
INSERT INTO projetos (id_projeto, id_contrato, titulo, descricao, data_inicio, data_fim_prevista, data_fim_real, valor_total, status, observacoes_gerais) VALUES (955, 300, 'Revisão dos PIAs', 'Acompanhamento rotineiro de processos para garantir a manutenção dos padrões institucionais.', '2026-01-13', NULL, NULL, 3500.00, 'concluído', NULL);
INSERT INTO projetos (id_projeto, id_contrato, titulo, descricao, data_inicio, data_fim_prevista, data_fim_real, valor_total, status, observacoes_gerais) VALUES (956, 300, 'Integração dos Atendimentos Multiprofissionais', 'Complexidade intelectual alta e backlog pesado. Conhecimento informal acumulado que precisa ser transposto para PIAs estruturados.', '2026-04-13', '2026-05-08', NULL, 2500.00, 'em andamento', NULL);
